// asumEx wraps cublasAsumEx.
func asumEx(handle Handle, n int32, x uintptr, xType DataType, incx int32, result uintptr, resultType DataType, executiontype DataType) error {
	if err := checkLibSym("cublasAsumEx"); err != nil {
		return err
	}
	return toError(fnasumEx(handle, n, x, xType, incx, result, resultType, executiontype))
}

// asumEx64 wraps cublasAsumEx_64.
func asumEx64(handle Handle, n int64, x uintptr, xType DataType, incx int64, result uintptr, resultType DataType, executiontype DataType) error {
	if err := checkLibSym("cublasAsumEx_64"); err != nil {
		return err
	}
	return toError(fnasumEx64(handle, n, x, xType, incx, result, resultType, executiontype))
}

// axpyEx This function is an API generalization of the routine cublasaxpy() where input data, output data and compute type can be specified independently.
//
// This function multiplies the vector x by the scalar α and adds it to the vector y overwriting the latest vector with the result. Hence, the performed operation is yj=α×xk+yj for i=1,…,n , k=1+(i−1)∗incx and j=1+(i−1)∗incy . Notice that the last two equations reflect 1-based indexing used for compatibility with Fortran. The datatypes combinations currently supported for [Handle.AxpyEx] are listed in the following table: The possible error values returned by this function and their meanings are listed below. For references please refer to NETLIB documentation: saxpy(), daxpy(), caxpy(), zaxpy()
//
//   - handle: Handle to the cuBLAS library context
//   - n: Number of elements in the vector x and y
//   - alpha: < type > scalar used for multiplication
//   - alphaType: Enumerant specifying the datatype of scalar alpha
//   - x: < type > vector with n elements
//   - xType: Enumerant specifying the datatype of vector x
//   - incx: Stride between consecutive elements of x
//   - y: < type > vector with n elements
//   - yType: Enumerant specifying the datatype of vector y
//   - incy: Stride between consecutive elements of y
//
// Returns:
//   - StatusExecutionFailed: The function failed to launch on the GPU.
//   - StatusInvalidValue: alphaType or xType or yType or executionType is not supported.
//   - StatusNotInitialized: The library was not initialized.
//   - StatusNotSupported: The combination of the parameters xType, yType, and executionType is not supported.
//   - StatusSuccess: The operation completed successfully.
//
// Wraps cublasAxpyEx.
func axpyEx(handle Handle, n int32, alpha uintptr, alphaType DataType, x uintptr, xType DataType, incx int32, y uintptr, yType DataType, incy int32, executiontype DataType) error {
	if err := checkLibSym("cublasAxpyEx"); err != nil {
		return err
	}
	return toError(fnaxpyEx(handle, n, alpha, alphaType, x, xType, incx, y, yType, incy, executiontype))
}

// axpyEx64 This function is an API generalization of the routine cublasaxpy() where input data, output data and compute type can be specified independently.
//
// This function multiplies the vector x by the scalar α and adds it to the vector y overwriting the latest vector with the result. Hence, the performed operation is yj=α×xk+yj for i=1,…,n , k=1+(i−1)∗incx and j=1+(i−1)∗incy . Notice that the last two equations reflect 1-based indexing used for compatibility with Fortran. The datatypes combinations currently supported for [Handle.AxpyEx] are listed in the following table: The possible error values returned by this function and their meanings are listed below. For references please refer to NETLIB documentation: saxpy(), daxpy(), caxpy(), zaxpy()
//
//   - handle: Handle to the cuBLAS library context
//   - n: Number of elements in the vector x and y
//   - alpha: < type > scalar used for multiplication
//   - alphaType: Enumerant specifying the datatype of scalar alpha
//   - x: < type > vector with n elements
//   - xType: Enumerant specifying the datatype of vector x
//   - incx: Stride between consecutive elements of x
//   - y: < type > vector with n elements
//   - yType: Enumerant specifying the datatype of vector y
//   - incy: Stride between consecutive elements of y
//
// Returns:
//   - StatusExecutionFailed: The function failed to launch on the GPU.
//   - StatusInvalidValue: alphaType or xType or yType or executionType is not supported.
//   - StatusNotInitialized: The library was not initialized.
//   - StatusNotSupported: The combination of the parameters xType, yType, and executionType is not supported.
//   - StatusSuccess: The operation completed successfully.
//
// Wraps cublasAxpyEx_64.
func axpyEx64(handle Handle, n int64, alpha uintptr, alphaType DataType, x uintptr, xType DataType, incx int64, y uintptr, yType DataType, incy int64, executiontype DataType) error {
	if err := checkLibSym("cublasAxpyEx_64"); err != nil {
		return err
	}
	return toError(fnaxpyEx64(handle, n, alpha, alphaType, x, xType, incx, y, yType, incy, executiontype))
}

